package com.valor.installation;
import com.valor.auth.*;
import com.valor.notifications.NotificationService;
import com.valor.realtime.RealtimeEventService;
import java.time.LocalDateTime;
import java.util.List;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service @Transactional
class InstallationAssignmentService {
 private final InstallationAssignmentRepository assignments; private final InstallationAssignmentHistoryRepository history; private final InstallationRequestRepository requests; private final AssetIdentityAccess access; private final WorkflowIdentityAccess identities; private final AuditService audit; private final NotificationService notifications; private final RealtimeEventService realtime;
 InstallationAssignmentService(InstallationAssignmentRepository a,InstallationAssignmentHistoryRepository h,InstallationRequestRepository r,AssetIdentityAccess x,WorkflowIdentityAccess i,AuditService au,NotificationService n,RealtimeEventService realtime){assignments=a;history=h;requests=r;access=x;identities=i;audit=au;notifications=n;this.realtime=realtime;}
 List<View> adminList(Long requestId){access.requireAdmin();return assignments.findByRequestIdOrderByAssignedAtDescIdDesc(requestId).stream().map(this::view).toList();}
 View assign(Long requestId,Long technicianId,String notes){access.requireAdmin();var r=requests.findById(requestId).orElseThrow(()->new IllegalArgumentException("Installation not found"));if(r.getStatus()!=InstallationStatus.IN_PROGRESS)throw conflict("Construction must be in progress before assigning construction technicians");var t=identities.activeTechnician(technicianId);var a=new InstallationAssignment();a.setRequest(r);a.setTechnician(t);a.setAssignedBy(access.actor());a.setNotes(clean(notes));a.setStatus(InstallationAssignmentStatus.ASSIGNED);var saved=assignments.saveAndFlush(a);record(saved,null,InstallationAssignmentStatus.ASSIGNED,"Assignment created");notifications.createSystemOnce(t.getUser().getId(),"INSTALLATION_ASSIGNMENT:"+saved.getId(),"Installation assignment","You have a new commercial installation assignment.");audit.record("INSTALLATION_ASSIGNMENT_CREATE","INSTALLATION_ASSIGNMENT",saved.getId(),"Installation technician assigned");return view(saved);}
 List<View> technicianList(){var t=identities.technician(access.actor());return assignments.findByTechnicianIdOrderByAssignedAtDescIdDesc(t.getId()).stream().map(this::view).toList();}
 View respond(Long id,long version,boolean accepted){var t=identities.technician(access.actor());var a=assignments.findByIdAndTechnicianId(id,t.getId()).orElseThrow(InstallationAssignmentService::denied);if(a.getVersion()!=version)throw conflict("Assignment changed; refresh before responding");if(a.getStatus()!=InstallationAssignmentStatus.ASSIGNED)throw conflict("Only a pending assignment can be responded to");var from=a.getStatus();a.setStatus(accepted?InstallationAssignmentStatus.ACCEPTED:InstallationAssignmentStatus.DECLINED);a.setRespondedAt(LocalDateTime.now());var saved=assignments.saveAndFlush(a);record(saved,from,saved.getStatus(),accepted?"Assignment accepted":"Assignment declined");audit.record(accepted?"INSTALLATION_ASSIGNMENT_ACCEPT":"INSTALLATION_ASSIGNMENT_DECLINE","INSTALLATION_ASSIGNMENT",id,accepted?"Technician accepted assignment":"Technician declined assignment");notifications.createSystemOnce(a.getAssignedBy().getId(),"INSTALLATION_ASSIGNMENT_RESPONSE:"+id+":"+saved.getVersion(),accepted?"Installation assignment accepted":"Installation assignment declined","A technician responded to a commercial installation assignment.");return view(saved);}
 View cancel(Long id,long version){access.requireAdmin();var a=assignments.findById(id).orElseThrow(()->new IllegalArgumentException("Assignment not found"));if(a.getVersion()!=version||a.getStatus()==InstallationAssignmentStatus.CANCELLED||a.getStatus()==InstallationAssignmentStatus.DECLINED)throw conflict("Assignment cannot be cancelled");var from=a.getStatus();a.setStatus(InstallationAssignmentStatus.CANCELLED);a.setCancelledAt(LocalDateTime.now());var saved=assignments.saveAndFlush(a);record(saved,from,saved.getStatus(),"Assignment cancelled");return view(saved);}
 private void record(InstallationAssignment a,InstallationAssignmentStatus from,InstallationAssignmentStatus to,String notes){var h=new InstallationAssignmentHistory();h.setAssignment(a);h.setChangedBy(access.actor());h.setFromStatus(from);h.setToStatus(to);h.setNotes(notes);history.save(h);realtime.publish("INSTALLATION_ASSIGNMENT_CHANGED","INSTALLATION_ASSIGNMENT",a.getId(),a.getStatus().name(),java.util.Set.of(a.getTechnician().getUser().getId(),a.getRequest().getCustomer().getUser().getId()));}
 private View view(InstallationAssignment a){return new View(a.getId(),a.getRequest().getId(),a.getTechnician().getId(),a.getTechnician().getEmployeeId(),a.getStatus(),a.getAssignedAt(),a.getRespondedAt(),a.getCancelledAt(),a.getNotes(),a.getVersion());}
 private static String clean(String s){return s==null||s.isBlank()?null:s.trim();} private static IllegalStateException conflict(String s){return new IllegalStateException(s);} private static AccessDeniedException denied(){return new AccessDeniedException("Access denied");}
 record View(Long id,Long installationRequestId,Long technicianProfileId,String employeeId,InstallationAssignmentStatus status,LocalDateTime assignedAt,LocalDateTime respondedAt,LocalDateTime cancelledAt,String notes,Long version){}
}
